/**
 * Splunk Node - Version 1
 * Discriminator: resource=user, operation=getAll
 */


interface Credentials {
  splunkApi: CredentialReference;
}

/** Retrieve many search configurations */
export type SplunkV1UserGetAllParams = {
  resource: 'user';
  operation: 'getAll';
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 50
 */
    limit?: number | Expression<number>;
};

export type SplunkV1UserGetAllNode = {
  type: 'n8n-nodes-base.splunk';
  version: 1;
  config: NodeConfig<SplunkV1UserGetAllParams> & { credentials?: Credentials };
};